import unittest
from candidate import add

class TestAddFunction(unittest.TestCase):
    def test_add_positive_integers(self):
        self.assertEqual(add(2, 3), 5)

    def test_add_negative_integers(self):
        self.assertEqual(add(-2, -3), -5)

    def test_add_mixed_signs(self):
        self.assertEqual(add(-2, 3), 1)

    def test_add_zero_with_positive(self):
        self.assertEqual(add(0, 5), 5)

    def test_add_zero_with_negative(self):
        self.assertEqual(add(0, -5), -5)

    def test_add_two_zeros(self):
        self.assertEqual(add(0, 0), 0)

    def test_add_large_numbers(self):
        self.assertEqual(add(10**18, 10**18), 2 * 10**18)

    def test_add_with_floats(self):
        self.assertAlmostEqual(add(2.5, 3.5), 6.0)

    def test_add_float_and_integer(self):
        self.assertAlmostEqual(add(2.1, 3), 5.1)

    def test_add_negative_float(self):
        self.assertAlmostEqual(add(-2.5, -3.5), -6.0)

    def test_add_very_small_floats(self):
        self.assertAlmostEqual(add(1e-10, 1e-10), 2e-10)

    def test_add_with_none(self):
        with self.assertRaises(TypeError):
            add(None, 5)

    def test_add_with_wrong_types(self):
        with self.assertRaises(TypeError):
            add("5", 3)

    def test_add_identical_numbers(self):
        self.assertEqual(add(7, 7), 14)

    def test_add_large_negative_numbers(self):
        self.assertEqual(add(-10**18, -10**18), -2 * 10**18)

    def test_add_negative_and_positive_large_numbers(self):
        self.assertEqual(add(-10**18, 10**18), 0)
